<?php
namespace App\Controllers;
use App\Core\{Database,Session,Csrf,Request,Response};
use App\Services\{NumberService,SubscriptionService,UploadService,EventService};
final class PortalController {
    private function view(string $view,array $data=[]):void{extract($data,EXTR_SKIP);$viewFile=BASE_PATH.'/app/Views/portal/'.$view.'.php';ob_start();require $viewFile;$content=ob_get_clean();require BASE_PATH.'/app/Views/portal/layout.php';}
    private function user():?array{return Session::get('portal_user');}
    private function requireUser():array{$u=$this->user();if(!$u)Response::redirect('/portal/login');return $u;}
    private function csrf():void{if(!Csrf::verify($_POST['_token']??$_SERVER['HTTP_X_CSRF_TOKEN']??null)){if(Request::wantsJson())Response::json(['success'=>false,'message'=>'Invalid CSRF token.','errors'=>[]],419);http_response_code(419);exit('Invalid CSRF token');}}
    public function loginForm():void{if($this->user())Response::redirect('/portal');$this->view('login',['title'=>'Customer Portal']);}
    public function login():void{$this->csrf();$code=strtoupper(trim((string)Request::input('company_code')));$email=strtolower(trim((string)Request::input('email')));$password=(string)Request::input('password');$db=Database::connection();$s=$db->prepare("SELECT pu.*,t.name tenant_name,t.status tenant_status,c.name customer_name FROM customer_portal_users pu JOIN tenants t ON t.id=pu.tenant_id JOIN customers c ON c.id=pu.customer_id AND c.tenant_id=pu.tenant_id WHERE t.company_code=? AND pu.email=? AND pu.status='active' LIMIT 1");$s->execute([$code,$email]);$u=$s->fetch();if(!$u||$u['tenant_status']!=='active'||!SubscriptionService::featureEnabled((int)$u['tenant_id'],'customer_portal')||!password_verify($password,$u['password_hash'])){Session::flash('portal_error','Company code, email, atau password salah.');Response::redirect('/portal/login');}Session::regenerate();Session::put('portal_user',['id'=>(int)$u['id'],'tenant_id'=>(int)$u['tenant_id'],'customer_id'=>(int)$u['customer_id'],'name'=>$u['name'],'email'=>$u['email'],'tenant_name'=>$u['tenant_name'],'customer_name'=>$u['customer_name']]);$db->prepare("UPDATE customer_portal_users SET last_login_at=NOW() WHERE id=?")->execute([$u['id']]);Response::redirect('/portal');}
    public function logout():void{$this->csrf();Session::forget('portal_user');Response::redirect('/portal/login');}
    public function dashboard():void{$u=$this->requireUser();$db=Database::connection();$t=$u['tenant_id'];$c=$u['customer_id'];$assets=$this->fetch($db,"SELECT * FROM customer_assets WHERE tenant_id=? AND customer_id=? AND deleted_at IS NULL ORDER BY id DESC",[$t,$c]);$requests=$this->fetch($db,"SELECT * FROM service_requests WHERE tenant_id=? AND customer_id=? AND deleted_at IS NULL ORDER BY id DESC LIMIT 20",[$t,$c]);$jobs=$this->fetch($db,"SELECT * FROM jobs WHERE tenant_id=? AND customer_id=? AND deleted_at IS NULL ORDER BY id DESC LIMIT 20",[$t,$c]);$quotes=$this->fetch($db,"SELECT * FROM quotations WHERE tenant_id=? AND customer_id=? AND deleted_at IS NULL ORDER BY id DESC LIMIT 20",[$t,$c]);$invoices=$this->fetch($db,"SELECT * FROM invoices WHERE tenant_id=? AND customer_id=? AND deleted_at IS NULL ORDER BY id DESC LIMIT 20",[$t,$c]);$contracts=$this->fetch($db,"SELECT * FROM contracts WHERE tenant_id=? AND customer_id=? AND deleted_at IS NULL ORDER BY id DESC",[$t,$c]);$warranties=$this->fetch($db,"SELECT w.*,j.job_number FROM warranties w JOIN jobs j ON j.id=w.job_id AND j.tenant_id=w.tenant_id WHERE w.tenant_id=? AND j.customer_id=? ORDER BY w.warranty_end DESC",[$t,$c]);$proofs=$this->fetch($db,"SELECT pp.*,i.invoice_number FROM customer_payment_proofs pp JOIN invoices i ON i.id=pp.invoice_id AND i.tenant_id=pp.tenant_id WHERE pp.tenant_id=? AND i.customer_id=? ORDER BY pp.id DESC LIMIT 20",[$t,$c]);$sites=$this->fetch($db,"SELECT id,site_name FROM customer_sites WHERE tenant_id=? AND customer_id=? AND deleted_at IS NULL ORDER BY site_name",[$t,$c]);$this->view('dashboard',['title'=>'Customer Portal','portalUser'=>$u,'assets'=>$assets,'requests'=>$requests,'jobs'=>$jobs,'quotes'=>$quotes,'invoices'=>$invoices,'contracts'=>$contracts,'warranties'=>$warranties,'sites'=>$sites,'proofs'=>$proofs]);}
    public function request():void{$this->csrf();$u=$this->requireUser();$problem=trim((string)Request::input('problem_description'));if($problem==='')Response::json(['success'=>false,'message'=>'Problem description wajib diisi.','errors'=>[]],422);$db=Database::connection();$num=NumberService::next($u['tenant_id'],'service_request','SR');$db->prepare("INSERT INTO service_requests(tenant_id,request_number,request_date,customer_id,site_id,service_category,problem_description,priority,requested_date,contact_person,status,created_at,updated_at) VALUES(?,?,CURDATE(),?,?,?,?,?,CURDATE(),?,'New',NOW(),NOW())")->execute([$u['tenant_id'],$num,$u['customer_id'],Request::input('site_id')?:null,Request::input('service_category'),$problem,Request::input('priority','Normal'),$u['name']]);Response::json(['success'=>true,'message'=>'Service request '.$num.' submitted.','data'=>['reload'=>true]]);}
    public function approve(string $id):void{$this->csrf();$u=$this->requireUser();$db=Database::connection();$q=$db->prepare("SELECT * FROM quotations WHERE id=? AND tenant_id=? AND customer_id=? AND deleted_at IS NULL");$q->execute([(int)$id,$u['tenant_id'],$u['customer_id']]);if(!$q->fetch())Response::json(['success'=>false,'message'=>'Quotation tidak ditemukan.','errors'=>[]],404);$db->beginTransaction();try{$db->prepare("UPDATE quotations SET status='Approved',updated_at=NOW() WHERE id=? AND tenant_id=?")->execute([(int)$id,$u['tenant_id']]);$db->prepare("INSERT INTO quotation_approvals(tenant_id,quotation_id,action,customer_name,customer_email,notes,approved_at,ip_address) VALUES(?,?,'Approved',?,?,?,NOW(),?)")->execute([$u['tenant_id'],(int)$id,$u['name'],$u['email'],Request::input('notes'),$_SERVER['REMOTE_ADDR']??null]);$db->commit();}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}Response::json(['success'=>true,'message'=>'Quotation approved.','data'=>['reload'=>true]]);}

    public function paymentProof(string $id): void {$this->csrf();$u=$this->requireUser();$amount=(float)Request::input('amount');if($amount<=0||empty($_FILES['attachment']))Response::json(['success'=>false,'message'=>'Amount dan bukti pembayaran wajib.','errors'=>[]],422);$db=Database::connection();$q=$db->prepare("SELECT id,balance,invoice_number FROM invoices WHERE id=? AND tenant_id=? AND customer_id=? AND deleted_at IS NULL AND balance>0");$q->execute([(int)$id,$u['tenant_id'],$u['customer_id']]);$inv=$q->fetch();if(!$inv)Response::json(['success'=>false,'message'=>'Invoice tidak ditemukan atau sudah lunas.','errors'=>[]],404);if($amount>(float)$inv['balance']+0.0001)Response::json(['success'=>false,'message'=>'Amount melebihi balance invoice.','errors'=>[]],422);try{$path=UploadService::store($_FILES['attachment'],$u['tenant_id'],'portal/payment-proofs/'.$id);$db->prepare("INSERT INTO customer_payment_proofs(tenant_id,invoice_id,portal_user_id,payment_date,amount,payment_method,bank,reference,attachment,notes,status,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,'Pending',NOW())")->execute([$u['tenant_id'],(int)$id,$u['id'],Request::input('payment_date')?:date('Y-m-d'),$amount,Request::input('payment_method','Bank Transfer'),Request::input('bank'),Request::input('reference'),$path,Request::input('notes')]);EventService::emit($u['tenant_id'],'payment.proof_submitted',['invoice_number'=>$inv['invoice_number'],'invoice_id'=>(int)$id,'amount'=>$amount]);}catch(\Throwable $e){Response::json(['success'=>false,'message'=>$e->getMessage(),'errors'=>[]],422);}Response::json(['success'=>true,'message'=>'Bukti pembayaran dikirim dan menunggu verifikasi finance.','data'=>['reload'=>true]]);}
    public function quotationPdf(string $id):never{$u=$this->requireUser();$db=Database::connection();$s=$db->prepare("SELECT q.*,t.name company_name,t.logo,t.invoice_footer,t.signature,t.stamp FROM quotations q JOIN tenants t ON t.id=q.tenant_id WHERE q.id=? AND q.tenant_id=? AND q.customer_id=? AND q.deleted_at IS NULL");$s->execute([(int)$id,$u['tenant_id'],$u['customer_id']]);$q=$s->fetch();if(!$q){http_response_code(404);exit;}$it=$this->fetch($db,"SELECT * FROM quotation_items WHERE quotation_id=? AND tenant_id=? ORDER BY id",[(int)$id,$u['tenant_id']]);$lines=['QUOTATION '.$q['quotation_number'],'Customer: '.$u['customer_name'],'Date: '.$q['quotation_date'].'   Valid Until: '.($q['valid_until']??'-'),''];foreach($it as $r)$lines[]=$r['description'].' | '.$r['quantity'].' '.($r['unit']??'').' | '.money($r['line_total']);$lines[]='';$lines[]='GRAND TOTAL: '.money($q['grand_total']);$lines[]='Status: '.$q['status'];\App\Services\SimplePdfService::output($q['quotation_number'].'.pdf',$lines,$q['company_name'],['logo_path'=>$q['logo'],'footer'=>$q['invoice_footer'],'attachments'=>[['path'=>$q['signature'],'label'=>'Authorized Signature'],['path'=>$q['stamp'],'label'=>'Company Stamp']]]);}
    public function invoicePdf(string $id):never{$u=$this->requireUser();$db=Database::connection();$s=$db->prepare("SELECT i.*,t.name company_name,t.logo,t.invoice_footer,t.signature,t.stamp FROM invoices i JOIN tenants t ON t.id=i.tenant_id WHERE i.id=? AND i.tenant_id=? AND i.customer_id=? AND i.deleted_at IS NULL");$s->execute([(int)$id,$u['tenant_id'],$u['customer_id']]);$i=$s->fetch();if(!$i){http_response_code(404);exit;}$it=$this->fetch($db,"SELECT * FROM invoice_items WHERE invoice_id=? AND tenant_id=? ORDER BY id",[(int)$id,$u['tenant_id']]);$lines=['INVOICE '.$i['invoice_number'],'Customer: '.$u['customer_name'],'Date: '.$i['invoice_date'].'   Due: '.($i['due_date']??'-'),''];foreach($it as $r)$lines[]=$r['description'].' | '.$r['quantity'].' '.($r['unit']??'').' | '.money($r['line_total']);$lines[]='';$lines[]='TOTAL: '.money($i['total']);$lines[]='PAID: '.money($i['paid']);$lines[]='BALANCE: '.money($i['balance']);$lines[]='Status: '.$i['status'];\App\Services\SimplePdfService::output($i['invoice_number'].'.pdf',$lines,$i['company_name'],['logo_path'=>$i['logo'],'footer'=>$i['invoice_footer'],'attachments'=>[['path'=>$i['signature'],'label'=>'Authorized Signature'],['path'=>$i['stamp'],'label'=>'Company Stamp']]]);}
    public function reportPdf(string $id):never{$u=$this->requireUser();$db=Database::connection();$s=$db->prepare("SELECT j.*,t.name company_name,t.logo,t.invoice_footer FROM jobs j JOIN tenants t ON t.id=j.tenant_id WHERE j.id=? AND j.tenant_id=? AND j.customer_id=? AND j.deleted_at IS NULL");$s->execute([(int)$id,$u['tenant_id'],$u['customer_id']]);$j=$s->fetch();if(!$j){http_response_code(404);exit;}$logs=$this->fetch($db,"SELECT activity,problem_found,action_taken,result,recommendation FROM job_work_logs WHERE job_id=? AND tenant_id=? ORDER BY id",[(int)$id,$u['tenant_id']]);$lines=['SERVICE REPORT '.$j['job_number'],'Customer: '.$u['customer_name'],'Status: '.$j['status'],'Description: '.$j['description'],''];foreach($logs as $l){$lines[]='Activity: '.($l['activity']??'');if($l['action_taken'])$lines[]='Action: '.$l['action_taken'];if($l['result'])$lines[]='Result: '.$l['result'];$lines[]='';}\App\Services\SimplePdfService::output('SERVICE-'.$j['job_number'].'.pdf',$lines,$j['company_name'],['logo_path'=>$j['logo'],'footer'=>$j['invoice_footer']]);}
    private function fetch(\PDO $db,string $sql,array $args):array{$s=$db->prepare($sql);$s->execute($args);return $s->fetchAll();}
}
